namespace sv_069d5df9b7564dc3a9429bd0690d83eb.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public ThemeMode Mode { get; set; } = ThemeMode.Light;
    public string AccentColor { get; set; } = "#0d6efd";

    public string CssClass => Mode switch
    {
        ThemeMode.Dark => "theme-dark",
        ThemeMode.System => "theme-system",
        _ => "theme-light"
    };
}

using Microsoft.AspNetCore.Components;

namespace sv_069d5df9b7564dc3a9429bd0690d83eb.Services;

/// <summary>
/// Scoped service that owns the current theme state and coordinates updates
/// between the DI-registered CascadingValueSource and all subscribing components.
/// One instance per circuit — each user gets independent state.
/// </summary>
public class ThemeService : IDisposable
{
    private readonly CascadingValueSource<ThemeInfo> _source;

    public ThemeInfo Current { get; private set; }

    /// <summary>
    /// Fired after the theme changes. Components subscribe in OnInitialized
    /// and unsubscribe in Dispose to trigger their own StateHasChanged.
    /// </summary>
    public event Action? OnChange;

    public ThemeService(CascadingValueSource<ThemeInfo> source)
    {
        _source = source;
        // Read the initial value that was seeded when the source was created.
        Current = new ThemeInfo();
    }

    public async Task SetThemeAsync(ThemeMode mode)
    {
        Current.Mode = mode;
        await NotifyAsync();
    }

    public async Task SetAccentColorAsync(string color)
    {
        Current.AccentColor = color;
        await NotifyAsync();
    }

    public async Task UpdateAsync(ThemeMode mode, string accentColor)
    {
        Current.Mode = mode;
        Current.AccentColor = accentColor;
        await NotifyAsync();
    }

    private async Task NotifyAsync()
    {
        // Push the updated value to all [CascadingParameter] subscribers
        // (works across render-mode boundaries).
        await _source.NotifyChangedAsync(Current);

        // Also fire the Action event so components using @inject ThemeService
        // can re-render (useful for static-SSR components that can't use
        // [CascadingParameter] reliably).
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        OnChange = null;
    }
}

