arguments.file_text:
@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <div class="mb-3">
        <label class="form-label fw-bold">Theme</label>
        <div class="btn-group d-flex" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                var isActive = mode == _selectedMode;
                <button type="button"
                        class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => SelectMode(mode)">
                    @mode
                </button>
            }
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold" for="accent-color">Accent Color</label>
        <div class="d-flex align-items-center gap-2">
            <input type="color" id="accent-color" class="form-control form-control-color"
                   value="@_accentColor" @onchange="OnAccentChanged" />
            <span class="text-muted">@_accentColor</span>
        </div>
    </div>

    <button class="btn btn-success" @onclick="Save">Save Preferences</button>

    @if (_saved)
    {
        <div class="alert alert-success mt-3 mb-0">Preferences saved!</div>
    }
</div>

@code {
    private ThemeMode _selectedMode;
    private string _accentColor = "#0d6efd";
    private bool _saved;

    protected override void OnInitialized()
    {
        _selectedMode = ThemeService.Current.Mode;
        _accentColor = ThemeService.Current.AccentColor;
    }

    private void SelectMode(ThemeMode mode)
    {
        _selectedMode = mode;
        _saved = false;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        _accentColor = e.Value?.ToString() ?? _accentColor;
        _saved = false;
    }

    private async Task Save()
    {
        await ThemeService.UpdateAsync(_selectedMode, _accentColor);
        _saved = true;
    }
}

